<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLButtonAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; import { getComboboxContext } from './combobox-context.svelte.js'; export interface Props extends Omit<HTMLButtonAttributes, 'children'> { children?: Snippet; ref?: HTMLButtonElement | null; } let { children, ref = $bindable(null), onclick, ...rest }: Props = $props(); const box = getComboboxContext(); const popover = getPopoverContext();</script><button bind:this={ref} {...rest} type="button" tabindex="-1" aria-label="Toggle suggestions" aria-controls={box.listId} disabled={box.disabled} data-popup-open={popover.open ? '' : undefined} onclick={composeEventHandlers(onclick, (event) => { popover.setOpen(!popover.open, 'trigger-press', event); box.input?.focus(); })}>{@render children?.()}</button>
